<script lang="ts">
  import { onMount, onDestroy, untrack } from 'svelte';
  import type { Language } from './i18n';
  import { prepareRestricted, launchRestricted, restrictedSessions, stopRestricted, discardRestricted, type RestrictedPlan, type RestrictedSession } from './restricted';
  let { language, initialPath = '' }: { language: Language; initialPath?: string } = $props();
  const it = $derived(language === 'it');
  let open = $state(false), path = $state(''), busy = $state(false), confirmed = $state(false), error = $state(''), message = $state(''), plan = $state<RestrictedPlan | null>(null), sessions = $state<RestrictedSession[]>([]), now = $state(Date.now());
  let alive = true, receivedPath = '';
  const expired = $derived(!!plan && plan.expires_at * 1000 <= now);
  const name = (value: string) => value.split('\\').pop() ?? value;
  async function refresh() { try { const values = await restrictedSessions(); if (alive) sessions = values; } catch (e) { if (alive) error = String(e); } }
  async function discard() { const old = plan; plan = null; confirmed = false; if (old) await discardRestricted(old.id).catch(() => {}); }
  async function prepare() { busy = true; error = ''; message = ''; await discard(); try { const next = await prepareRestricted(path.trim()); if (alive) { plan = next; now = Date.now(); } else await discardRestricted(next.id); } catch (e) { error = String(e); } finally { busy = false; } }
  async function launch() { if (!plan || !confirmed || expired || busy) return; const submitted = plan; plan = null; confirmed = false; busy = true; error = ''; try { await launchRestricted(submitted.id); message = it ? 'Copia avviata con token AppContainer e limiti verificati. L’app originale conserva i suoi permessi.' : 'Copy launched with verified AppContainer token and limits. The original app keeps its permissions.'; await refresh(); } catch (e) { await refresh(); error = (it ? 'Esito dell’avvio non confermato. Controlla le prove elencate o aggiorna lo stato. ' : 'Launch outcome unconfirmed. Check listed trials or refresh status. ') + String(e); } finally { busy = false; } }
  async function stop(id: string) { busy = true; error = ''; message = ''; try { await stopRestricted(id); message = it ? 'Prova terminata; copia e profilo rimossi.' : 'Trial stopped; copy and profile removed.'; await refresh(); } catch (e) { await refresh(); error = (it ? 'Chiusura o rimozione non confermata. ' : 'Stop or removal unconfirmed. ') + String(e); } finally { busy = false; } }
  $effect(() => { const incoming = initialPath; untrack(() => { if (incoming && incoming !== receivedPath) { receivedPath = incoming; void discard(); path = incoming; open = true; } }); });
  onMount(() => { path = initialPath; open = !!initialPath; void refresh(); const timer = setInterval(() => { now = Date.now(); if (open && sessions.length && !busy) void refresh(); }, 2000); return () => clearInterval(timer); });
  onDestroy(() => { alive = false; void discard(); });
</script>
<details class="restricted-panel" bind:open>
  <summary>{it ? 'Avvio limitato · AppContainer' : 'Restricted launch · AppContainer'}</summary>
  <p>{it ? 'Prova una copia del programma con meno permessi sul PC. Adatto soprattutto a eseguibili portabili; le app con DLL o più processi possono non funzionare.' : 'Try a copy with fewer permissions on this PC. Best suited to portable executables; apps requiring extra DLLs or processes may fail.'}</p>
  <div class="limits"><span>{it ? 'Senza capability rete' : 'No network capabilities'}</span><span>{it ? 'Un processo · 512 MiB' : 'One process · 512 MiB'}</span><span>{it ? 'Copia eseguibile in sola lettura' : 'Read-only executable copy'}</span></div>
  <button class="text-button" disabled={busy} onclick={() => { error = ''; void refresh(); }}>{it ? 'Aggiorna stato prove' : 'Refresh trial status'}</button>
  <form onsubmit={e => { e.preventDefault(); void prepare(); }}><label for="restricted-path">{it ? 'Eseguibile da provare' : 'Executable to try'}</label><div class="row"><input id="restricted-path" bind:value={path} disabled={busy} maxlength="2048" placeholder="C:\Downloads\app.exe" oninput={() => { void discard(); message = ''; }} /><button class="button primary" disabled={busy || !path.trim() || sessions.length >= 2}>{it ? 'Prepara avvio limitato' : 'Prepare restricted launch'}</button></div></form>
  {#if plan}<section class="preview" aria-label={it ? 'Anteprima avvio limitato' : 'Restricted launch preview'}><h3>{name(plan.executable)}</h3><code>{plan.executable}</code><details><summary>SHA-256</summary><code>{plan.sha256}</code></details><p>{it ? 'Premendo Avvia, piko copia questo file e lo esegue sul PC in AppContainer. Nessuna VM. Può scrivere solo dove Windows concede accesso, incluso il suo profilo temporaneo, e leggere risorse condivise di Windows.' : 'Launch copies this file and executes it on this PC in AppContainer. No VM. It can write where Windows grants access, including its temporary profile, and read shared Windows resources.'}</p><label class="confirmation"><input type="checkbox" bind:checked={confirmed} disabled={busy || expired} />{it ? 'Confermo l’esecuzione di questa copia con i limiti indicati.' : 'I confirm running this copy with the stated limits.'}</label>{#if expired}<p class="warning">{it ? 'Anteprima scaduta. Preparala di nuovo.' : 'Preview expired. Prepare it again.'}</p>{/if}<div class="row"><button class="button primary" disabled={busy || !confirmed || expired} onclick={launch}>{it ? 'Avvia copia limitata' : 'Launch restricted copy'}</button><button class="button secondary" disabled={busy} onclick={discard}>{it ? 'Annulla' : 'Cancel'}</button></div></section>{/if}
  {#if error}<p class="warning" role="alert">{error}</p>{/if}{#if message}<p class="message" role="status">{message}</p>{/if}
  {#each sessions as session (session.id)}<article><div><strong>{name(session.executable)}</strong><small>{session.running ? (it ? 'In esecuzione' : 'Running') : (it ? 'Terminata' : 'Exited')} · PID {session.pid}</small><details><summary>{it ? 'Percorsi e impronta' : 'Paths and fingerprint'}</summary><code>{session.executable}</code><code>{session.sha256}</code><code>{session.data_directory}</code></details></div><button class="button secondary" disabled={busy} onclick={() => stop(session.id)}>{it ? 'Termina e rimuovi prova' : 'Stop and remove trial'}</button></article>{/each}
  <details class="scope"><summary>{it ? 'Ambito e compatibilità' : 'Scope and compatibility'}</summary><p>{it ? 'I limiti valgono per questa copia e i suoi processi, non per ogni avvio dell’app installata. AppContainer non vieta ogni lettura fuori dalla cartella: le ACL di Windows possono consentire risorse comuni. Nessun accesso personale è aggiunto da piko. Senza capability rete non sono consentite connessioni dirette; l’accesso tramite broker autorizzati dipende da Windows. L’originale e gli aggiornamenti dell’app installata non sono congelati. La copia resta bloccata contro modifiche durante la prova. Chiudendo piko, Windows termina il job; dopo un arresto anomalo possono restare cartelle/profili da controllare. Non vengono copiati DLL, dati o dipendenze. Il programma potrebbe non partire o chiudersi subito.' : 'Limits apply to this copy and its processes, not every launch of the installed app. AppContainer does not deny every outside-folder read: Windows ACLs may allow shared resources. piko grants no access to personal data. Direct network connections lack capabilities; access through authorized brokers depends on Windows. The original and installed app updates are not frozen. The executable copy is locked against modification during the trial. Closing piko terminates the job; an abnormal shutdown may leave folders/profiles to inspect. DLLs, data and dependencies are not copied. The app may fail to launch or exit immediately.'}</p></details>
</details>
<style>
  .restricted-panel{padding:24px;border:1px solid var(--border);border-radius:14px;background:var(--surface);min-width:0} summary{cursor:pointer;font-size:.88rem} p{color:var(--muted);font-size:.81rem;margin:13px 0}.limits,.row{display:flex;flex-wrap:wrap;gap:8px}.limits span{background:var(--selection-soft);color:var(--selection);padding:6px 9px;border-radius:6px;font-size:.72rem}label{display:block;font-size:.8rem;margin:16px 0 8px}input:not([type=checkbox]){flex:1;min-width:140px;border:1px solid var(--border-strong);border-radius:8px;padding:10px;background:var(--surface);color:var(--text)}.preview{margin:18px 0;padding:18px;background:var(--contain-soft);border:1px solid var(--contain-border);border-radius:10px}code{display:block;overflow-wrap:anywhere;margin:8px 0}.confirmation{display:flex;align-items:start;gap:10px}.warning{background:var(--warning-surface);color:var(--warning);padding:12px;border-radius:8px}.message{background:var(--accent-soft);color:var(--accent-ink);padding:12px;border-radius:8px}article{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;padding:16px 0;border-top:1px solid var(--border)}small{display:block;color:var(--muted);margin-top:6px}.scope{margin-top:18px}.button{white-space:normal}
</style>
